// The narrated walkthrough video: chapter lookups for the in-app player and its deep links.
// The chapter list itself is generated by apps/web/walkthrough/publish.sh into walkthrough-chapters.ts.

export type WalkthroughChapter = { step: string; label: string; t: number };

export type WalkthroughManifest = {
  url: string;
  poster: string;
  captions: string;
  duration: number;
  chapters: readonly WalkthroughChapter[];
};

/** Seconds as m:ss, rounded down: 75.9 -> "1:15". */
export function formatTime(seconds: number): string {
  const whole = Math.max(0, Math.floor(Number.isFinite(seconds) ? seconds : 0));
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
}

// A seek to a chapter's start can land a few microseconds short of it (129.7 reads back as 129.699998).
const SEEK_TOLERANCE = 0.05;

/** Index of the chapter playing at `time`: the last one that has started, or 0 before the first. */
export function chapterFor(chapters: readonly WalkthroughChapter[], time: number): number {
  let index = 0;
  chapters.forEach((chapter, i) => {
    if (chapter.t <= time + SEEK_TOLERANCE) index = i;
  });
  return index;
}

export function chapterIndex(chapters: readonly WalkthroughChapter[], step: string | null): number | null {
  if (!step) return null;
  const index = chapters.findIndex((chapter) => chapter.step === step);
  return index === -1 ? null : index;
}

/** How long a chapter runs: up to the next chapter, or to the end of the video for the last one. */
export function chapterLength(manifest: WalkthroughManifest, step: string): number | null {
  const index = chapterIndex(manifest.chapters, step);
  if (index === null) return null;
  const end = manifest.chapters[index + 1]?.t ?? manifest.duration;
  return Math.max(0, end - manifest.chapters[index].t);
}

/**
 * The chapter a link asks for. `?video=<step>` (or CALIPER's `#v=<step>`) opens the player at that step;
 * `?video` or `?video=1` opens it at the start. Unknown steps open at the start too, so an old link still works.
 * Returns null when the link asks for no video.
 */
export function parseVideoParam(
  search: string,
  hash: string,
  chapters: readonly WalkthroughChapter[]
): { step: string } | null {
  const query = new URLSearchParams(search.startsWith("?") ? search.slice(1) : search);
  const fromHash = new URLSearchParams(hash.startsWith("#") ? hash.slice(1) : hash).get("v");
  const requested = query.has("video") ? query.get("video") ?? "" : fromHash;
  if (requested === null) return null;
  const first = chapters[0]?.step ?? "intro";
  return { step: chapterIndex(chapters, requested.trim()) === null ? first : requested.trim() };
}

/** A shareable link to the public walkthrough page, opened at a step. */
export function walkthroughHref(step?: string): string {
  return step ? `/walkthrough?video=${encodeURIComponent(step)}` : "/walkthrough";
}
